create table public.chat_story_circles(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 80),usernames text[] not null,unique(owner_id,name));
alter table public.chat_story_circles enable row level security;revoke all on public.chat_story_circles from anon,authenticated;grant select,delete on public.chat_story_circles to authenticated;
create policy circles_owner on public.chat_story_circles for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create table public.chat_stories(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,body text not null default '' check(length(body)<=2000),media_path text,media_type text,music_url text,created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '24 hours',client_operation_id text not null,unique(owner_id,client_operation_id));
create table public.chat_story_recipients(story_id uuid not null references public.chat_stories(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,primary key(story_id,user_id));
create index chat_story_recipients_user_idx on public.chat_story_recipients(user_id,story_id);
create or replace function public.can_view_chat_story(target_story_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.chat_stories s where s.id=target_story_id and s.expires_at>now() and(s.owner_id=auth.uid() or exists(select 1 from public.chat_story_recipients r where r.story_id=s.id and r.user_id=auth.uid())));$$;
alter table public.chat_stories enable row level security;alter table public.chat_story_recipients enable row level security;
revoke all on public.chat_stories,public.chat_story_recipients from anon,authenticated;grant select,delete on public.chat_stories to authenticated;grant select on public.chat_story_recipients to authenticated;
create policy stories_allowed_read on public.chat_stories for select to authenticated using(public.can_view_chat_story(id));
create policy stories_owner_delete on public.chat_stories for delete to authenticated using(owner_id=(select auth.uid()));
create policy story_recipients_private on public.chat_story_recipients for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.chat_stories s where s.id=story_id and s.owner_id=(select auth.uid())));
create table public.chat_story_reactions(story_id uuid not null references public.chat_stories(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,reaction text not null check(reaction in ('❤️','👍','😂','🎉','😮','😢')),created_at timestamptz not null default now(),primary key(story_id,user_id));
alter table public.chat_story_reactions enable row level security;revoke all on public.chat_story_reactions from anon,authenticated;grant select,insert,update,delete on public.chat_story_reactions to authenticated;
create policy story_reaction_private_read on public.chat_story_reactions for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.chat_stories s where s.id=story_id and s.owner_id=(select auth.uid())));
create policy story_reaction_own_insert on public.chat_story_reactions for insert to authenticated with check(user_id=(select auth.uid()) and public.can_view_chat_story(story_id));
create policy story_reaction_own_update on public.chat_story_reactions for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and public.can_view_chat_story(story_id));
create policy story_reaction_own_delete on public.chat_story_reactions for delete to authenticated using(user_id=(select auth.uid()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('luo-stories','luo-stories',false,52428800,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','audio/mpeg','audio/mp4','audio/ogg','audio/webm']);
create policy stories_storage_owned_insert on storage.objects for insert to authenticated with check(bucket_id='luo-stories' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy stories_storage_owned_delete on storage.objects for delete to authenticated using(bucket_id='luo-stories' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy stories_storage_allowed_read on storage.objects for select to authenticated using(bucket_id='luo-stories' and((storage.foldername(name))[1]=(select auth.uid())::text or exists(select 1 from public.chat_stories s where s.media_path=name and public.can_view_chat_story(s.id))));
create or replace function public.save_chat_story_circle(circle_name text,recipient_usernames text[]) returns uuid language plpgsql security definer set search_path='' as $$ declare result uuid;begin
 if auth.uid() is null or length(trim(circle_name)) not between 1 and 80 or coalesce(cardinality(recipient_usernames),0)>100 or exists(select 1 from unnest(recipient_usernames) u where not exists(select 1 from public.profiles p where p.username=u)) then raise exception 'Enter a circle name and up to 100 valid exact usernames';end if;
 insert into public.chat_story_circles(owner_id,name,usernames) values(auth.uid(),trim(circle_name),recipient_usernames) on conflict(owner_id,name) do update set usernames=excluded.usernames returning id into result;return result;end;$$;
create or replace function public.create_private_chat_story(story_body text,uploaded_path text,uploaded_type text,music_link text,recipient_usernames text[],operation_id text) returns uuid language plpgsql security definer set search_path='' as $$
declare result uuid;actor uuid:=auth.uid();begin
 if actor is null or length(coalesce(story_body,''))>2000 or coalesce(cardinality(recipient_usernames),0)>100 or length(coalesce(operation_id,'')) not between 8 and 100 or (coalesce(story_body,'')='' and uploaded_path is null and coalesce(music_link,'')='') then raise exception 'Add text, supported media, or a music link';end if;
 if music_link is not null and(length(music_link)>2000 or music_link!~'^https://') then raise exception 'Use an HTTPS music link';end if;
 if exists(select 1 from unnest(recipient_usernames) u where not exists(select 1 from public.profiles p where p.username=u)) then raise exception 'A selected username does not exist';end if;
 if uploaded_path is not null and not exists(select 1 from storage.objects o where o.bucket_id='luo-stories' and o.name=uploaded_path and split_part(o.name,'/',1)=actor::text and o.owner_id=actor::text and o.metadata->>'mimetype'=uploaded_type) then raise exception 'Upload a supported story file first';end if;
 insert into public.chat_stories(owner_id,body,media_path,media_type,music_url,client_operation_id) values(actor,coalesce(story_body,''),uploaded_path,uploaded_type,music_link,operation_id) on conflict(owner_id,client_operation_id) do nothing returning id into result;
 if result is null then select id into result from public.chat_stories where owner_id=actor and client_operation_id=operation_id;return result;end if;
 insert into public.chat_story_recipients(story_id,user_id) select result,p.id from public.profiles p where p.username=any(recipient_usernames) and p.id<>actor on conflict do nothing;return result;
end;$$;
create or replace function public.queue_deleted_story_media() returns trigger language plpgsql security definer set search_path='' as $$begin if old.media_path is not null then insert into public.storage_cleanup_queue(bucket_id,object_path) values('luo-stories',old.media_path);end if;return old;end;$$;
revoke all on function public.queue_deleted_story_media() from public,anon,authenticated;
create trigger deleted_story_cleanup after delete on public.chat_stories for each row execute function public.queue_deleted_story_media();
create or replace function public.chat_account_storage_paths(target_user_id uuid) returns table(bucket_id text,object_path text) language sql stable security definer set search_path='' as $$ select o.bucket_id,o.name from storage.objects o where(o.bucket_id in('avatars','luo-stories') and split_part(o.name,'/',1)=target_user_id::text) or(o.bucket_id='chat-media' and split_part(o.name,'/',2)=target_user_id::text);$$;
revoke all on function public.can_view_chat_story(uuid),public.save_chat_story_circle(text,text[]),public.create_private_chat_story(text,text,text,text,text[],text) from public,anon;
grant execute on function public.can_view_chat_story(uuid),public.save_chat_story_circle(text,text[]),public.create_private_chat_story(text,text,text,text,text[],text) to authenticated;
select cron.schedule('luo-private-story-expiry','*/5 * * * *',$q$delete from public.chat_stories where expires_at<=now();$q$);
